-- 2026-11-11 修正 A1-1.1.2“PC 机组成”子项编号，避免与顶层 1、撞号
begin;
create temp table _kb_fix(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kb_fix values (41, $kbfix$[{"t":"list","id":"a1-1-1-2-b1","imp":"core","items":["1、==PC 机组成==：","（1）^^输入单元（input unit）^^：==计算机的“接收”部分==，从各种输入设备接收信息（数据和计算机程序），并将这些信息放到其他单元中，使信息得以处理。如今大多数信息通过键盘和鼠标输入计算机，将来也可能通过语音输入或扫描图形获得。","（2）^^输出单元（output unit）^^：==计算机的“发送”部分==，将计算机处理过的信息送到不同输出设备中，向计算机外部提供所需的信息。如今大多数信息通过屏幕显示、书面打印或用于控制其他设备输出。","（3）^^内存单元（memory unit）^^：==计算机中快速访问、低容量的“库存”部分==。","2、==输入设备==：把信息送入计算机的设备（以二进制形式）。^^常用的输入设备：键盘，鼠标、扫描仪、麦克风等^^","3、==输出设备==：将计算机中的信息输出的设备（文字、图形、图像、声音等）。^^常用的输出设备：显示器、打印机、绘图仪、扬声器等。^^","4、==I/O 控制器与常见输入输出设备接口==：I/O 控制器（input 和 output）负责输入输出控制。 常见输入设备：鼠标、键盘、扫描仪、数码相机、摄像头。 常见输出设备：显示器、打印机、绘图仪。 常用接口：串行口 COM（9 针）；并行口 LPT1（接打印机）；VGA 口（接显示器）；PS/2 口（接鼠标、键盘）；USB 高速通用串行接口，可接鼠标、键盘、外置光驱、U 盘、打印机等，有 1.1 和 2.0 两种类型，1.1 全速速率为 12Mb/s（约 1.5MB/s）。","5、^^鼠标滚轮的作用^^：^^某些鼠标器左右两按键的中间有一个滚轮^^，它的作用通常是控制屏幕内容上下移动，与窗口右边框滚动条的功能一样。注意：按动鼠标按键后，计算机具体做什么，由正在运行的软件决定。","6、==CPU 即中央处理器==，由==运算器（ALU）==、==控制器(CU)==和==寄存器组（GPR）==构成用于执行系统软件和应用软件的处理器称为CPU，CPU 是计算机必不可少的核心组成部件。","^^运算器^^用来对数据进行^^各种算术^^或^^逻辑运算^^，所以称为算术逻辑部件(ALU)，参加ALU 运算的操作数通常来自通用寄存器GPR ，运算结果也送回通用寄存器GPR。","（1）^^运算器（ALU）:对数据进行算术运算、逻辑运算等。^^","（2）^^控制器（CU）:控制单元，取出指令并保存，解释指令的功能，由此产生控制各部件工作的信号，执行指令。^^","7、==CPU== 的==主要任务==是==执行指令==，它按指令的规定对数据进行操作。","8、==使用双核(或多核)处理器的PC 机中，是几个CPU？集成在一块芯片上，物理上只有一个，逻辑上是两（或多）个。=="],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-2-b2","imp":"core","kind":"tip","text":"CPU 是计算机核心，由==运算器（ALU）、控制器、通用寄存器组（GPR）及内部总线==构成；其中==通用寄存器组是 CPU 内部存取速度最快==的存储单元；常用输入设备（键盘、鼠标、扫描仪）与输出设备（显示器、打印机、绘图仪）需熟练归类区分。","title":"考向复习提示：CPU 组成与常用 I/O 设备"},{"t":"callout","id":"a1-1-1-2-b3","imp":"core","kind":"trap","text":"专转本必考题：==程序计数器（PC）的作用是“存放 CPU 即将执行的下一条指令在内存中的地址”==，指令取出后 PC 自动加 1（指向紧随其后的下一条指令）；混淆选项常将 PC 功能说成“存放正在执行的指令”或“存放指令的操作数”，注意正在执行的指令存放于==指令寄存器（IR）==！","title":"高频易错陷阱：程序计数器 PC 的功能常考点"}]$kbfix$::jsonb, $kbfixsearch$A1-1.1.2 常见的输入设备和输出设备，中央处理器。 1、PC 机组成： （1）输入单元（input unit）：计算机的“接收”部分，从各种输入设备接收信息（数据和计算机程序），并将这些信息放到其他单元中，使信息得以处理。如今大多数信息通过键盘和鼠标输入计算机，将来也可能通过语音输入或扫描图形获得。 （2）输出单元（output unit）：计算机的“发送”部分，将计算机处理过的信息送到不同输出设备中，向计算机外部提供所需的信息。如今大多数信息通过屏幕显示、书面打印或用于控制其他设备输出。 （3）内存单元（memory unit）：计算机中快速访问、低容量的“库存”部分。 2、输入设备：把信息送入计算机的设备（以二进制形式）。常用的输入设备：键盘，鼠标、扫描仪、麦克风等 3、输出设备：将计算机中的信息输出的设备（文字、图形、图像、声音等）。常用的输出设备：显示器、打印机、绘图仪、扬声器等。 4、I/O 控制器与常见输入输出设备接口：I/O 控制器（input 和 output）负责输入输出控制。 常见输入设备：鼠标、键盘、扫描仪、数码相机、摄像头。 常见输出设备：显示器、打印机、绘图仪。 常用接口：串行口 COM（9 针）；并行口 LPT1（接打印机）；VGA 口（接显示器）；PS/2 口（接鼠标、键盘）；USB 高速通用串行接口，可接鼠标、键盘、外置光驱、U 盘、打印机等，有 1.1 和 2.0 两种类型，1.1 全速速率为 12Mb/s（约 1.5MB/s）。 5、鼠标滚轮的作用：某些鼠标器左右两按键的中间有一个滚轮，它的作用通常是控制屏幕内容上下移动，与窗口右边框滚动条的功能一样。注意：按动鼠标按键后，计算机具体做什么，由正在运行的软件决定。 6、CPU 即中央处理器，由运算器（ALU）、控制器(CU)和寄存器组（GPR）构成用于执行系统软件和应用软件的处理器称为CPU，CPU 是计算机必不可少的核心组成部件。 运算器用来对数据进行各种算术或逻辑运算，所以称为算术逻辑部件(ALU)，参加ALU 运算的操作数通常来自通用寄存器GPR ，运算结果也送回通用寄存器GPR。 （1）运算器（ALU）:对数据进行算术运算、逻辑运算等。 （2）控制器（CU）:控制单元，取出指令并保存，解释指令的功能，由此产生控制各部件工作的信号，执行指令。 7、CPU 的主要任务是执行指令，它按指令的规定对数据进行操作。 8、使用双核(或多核)处理器的PC 机中，是几个CPU？集成在一块芯片上，物理上只有一个，逻辑上是两（或多）个。 考向复习提示：CPU 组成与常用 I/O 设备 CPU 是计算机核心，由运算器（ALU）、控制器、通用寄存器组（GPR）及内部总线构成；其中通用寄存器组是 CPU 内部存取速度最快的存储单元；常用输入设备（键盘、鼠标、扫描仪）与输出设备（显示器、打印机、绘图仪）需熟练归类区分。 高频易错陷阱：程序计数器 PC 的功能常考点 专转本必考题：程序计数器（PC）的作用是“存放 CPU 即将执行的下一条指令在内存中的地址”，指令取出后 PC 自动加 1（指向紧随其后的下一条指令）；混淆选项常将 PC 功能说成“存放正在执行的指令”或“存放指令的操作数”，注意正在执行的指令存放于指令寄存器（IR）！$kbfixsearch$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kb_fix loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
